export type GlossaryTerm = { term: string; definition: string }

/** Términos del glosario institucional de INAPI, redactados para lectura en el portal. */
export const GLOSSARY_TERMS: GlossaryTerm[] = [
  { term: 'Abandono', definition: 'Instancia administrativa a la cual llega una solicitud en el caso que el solicitante no de respuesta a alguno de los requerimientos establecidos por la Ley Nº 19039, dentro de los plazos que ella establece.' },
  { term: 'Activos intangibles', definition: 'Los activos intangibles son aquellos recursos obtenidos por una empresa que no son de naturaleza material.' },
  { term: 'Activos tangibles', definition: 'Se consideran activos tangibles todos los bienes de naturaleza material susceptibles de ser percibidos por los sentidos.' },
  { term: 'Acuerdo de confidencialidad', definition: 'Contrato que regula las condiciones de la relación jurídica entre una persona que divulga información confidencial y otra que recibe la información.' },
  { term: 'ADPIC', definition: 'Es un acuerdo de normas mínimas, que permite a los Miembros prestar una protección más amplia a la propiedad intelectual si así lo desean. Se les deja libertad para determinar el método apropiado de aplicación de las disposiciones del Acuerdo en el marco de sus sistemas y usos jurídicos.' },
  { term: 'Adquisición de know-how y tecnología no incorporada', definition: 'Obtención de tecnología externa en forma de patentes, inventos no patentados, licencias, divulgaciones de know-how, diseños, marcas, patrones, entre otros.' },
  { term: 'Adquisición de tecnología incorporada', definition: 'Obtención de equipos y maquinarias con mejoramientos que generan innovaciones tecnológicas en productos o procesos implementados por la empresa.' },
  { term: 'Apelación', definition: 'Es un recurso ordinario que la Ley de Propiedad Industrial concede a la parte que se siente agraviada por una sentencia definitiva o interlocutoria dictada por el Director Nacional de INAPI, para recurrir al TDPI a fin de que este último la revise, pudiendo confirmarla, revocarla o modificarla. Mayor información en <https://www.tdpi.cl/>' },
  { term: 'Desarchivo de Patentes', definition: 'Las solicitudes que no cumplen con alguna exigencia de tramitación, dentro de los plazos señalados en la ley de Propiedad Industrial y su reglamento, se tendrán por abandonadas, procediéndose a su archivo. Pese a lo anterior, el solicitante puede requerir su desarchivo siempre que subsane las exigencias de tramitación dentro de los cuarenta y cinco días siguientes, contados desde la fecha del abandono, sin que pierda el derecho de prioridad, para lo cual deberá acreditar el pago de una tasa equivalente a dos unidades tributarias mensuales. Vencido el plazo sin que se hayan subsanado los errores u omisiones, la solicitud se tendrá por abandonada definitivamente.' },
  { term: 'Patentes Provisionales', definition: 'Tipo de solicitud de patente en la que cualquier persona que aún no pueda cumplir con todos los elementos de una solicitud de patente para su presentación, pueda presentar esta solicitud, denominada patente provisional, que el Instituto reconocerá por el término de doce meses, previo pago de la tasa correspondiente. Antes de vencer los 12 meses se debe presentar patente definitiva, cumpliendo los requisitos completos establecidos por la Ley de Propiedad Industrial y su reglamento, en español. La vigencia de la patente definitiva se cuenta a partir de la fecha de presentación de la solicitud provisional.' },
  { term: 'Aplicación Industrial', definition: 'Requisito de patentabilidad para las invenciones y modelos de utilidad que implica que el objeto de la solicitud es factible de ser reproducido o utilizado en la industria, entendida ésta en su concepto más amplio.' },
  { term: 'Bienes inmateriales', definition: 'Los bienes inmateriales o incorporales son aquellos que no tienen presencia corpórea o física.' },
  { term: 'Bioinformática', definition: 'Área del conocimiento dedicada a la construcción de bases de datos sobre genomas, secuenciamiento de proteínas, y la modelación matemática de complejos procesos biológicos y de biología de sistemas.' },
  { term: 'Biotecnología', definition: 'Conjunto de técnicas en las que se emplean organismos vivos (o parte de ellos) para fabricar o modificar productos, mejorar plantas o animales, o crear microorganismos para usos específicos.' },
  { term: 'Búsqueda del estado de la técnica', definition: 'Las oficinas de patentes realizan una búsqueda para determinar el estado de la técnica en el ámbito específico y al área técnica al que corresponda la invención.' },
  { term: 'Certificado de anotaciones marginales', definition: 'Una anotación marginal es un texto que se estampa al costado del documento original en el cual se indica cualquier cambio que haya sufrido la solicitud o el registro durante su vigencia, como por ejemplo: cambios de representante, cambio de dirección del titular, transferencia, etc. Por tanto el Certificado de anotaciones marginales constatará todos aquellos cambios de la solicitud o el registro, en tanto éstos hayan sido informados por el titular o representante de la solicitud o el registro al INAPI.' },
  { term: 'Certificado de registro', definition: 'Este documento constatará que la solicitud de derecho que se indica se encuentra concedida. Los certificados pueden ser de marcas comerciales, patentes de invención, modelos de utilidad, dibujos y diseños industriales, esquemas de trazado o topografías de circuitos integrados, indicaciones geográficas o denominaciones de origen.' },
  { term: 'Certificado de solicitud', definition: 'Este documento constatará que la solicitud que se indica se encuentra en proceso de tramitación. Los certificados pueden ser de marcas comerciales, patentes de invención, modelos de utilidad, dibujos y diseños industriales, esquemas de trazado o topografías de circuitos integrados, indicaciones geográficas o denominaciones de origen.' },
  { term: 'Cesión', definition: 'Es el documento a través del cual el inventor cede al solicitante los derechos patrimoniales del derecho que se está solicitando. La presentación del documento de cesión se rige por lo establecido en el 14 de la Ley 19.039.' },
  { term: 'CIP - clasificación internacional de patentes', definition: 'Sistema jerárquico donde el ámbito de la tecnología se divide en una serie de secciones, clases, subclases y grupos. La CIP fue concebida para permitir una clasificación uniforme de los documentos de patentes a nivel internacional. Su objetivo es ser un instrumento eficaz de búsqueda para la recuperación de los documentos de patentes, así como para determinar la novedad y actividad inventiva de las divulgaciones técnicas de una solicitud de patente.' },
  { term: 'Circuito Integrado', definition: 'Un producto, en su forma final o intermedia destinado a realizar una función electrónica, en el que los elementos, al menos uno de los cuales debe ser "activo", y alguna o todas las interconexiones, formen parte integrante del cuerpo o de la superficie de una pieza de material.' },
  { term: 'Clasificador de Diseños Industriales', definition: 'Es Clasificador Internacional de Dibujos y Modelos Industriales establecido por el Arreglo de Locarno del 8 de Octubre de 1968 y sus posteriores modificaciones.' },
  { term: 'Clasificador de Marcas Comerciales', definition: 'Es Clasificador Internacional de Productos y Servicios, establecido por el Arreglo de Niza del 15 de Junio de 1957 y sus posteriores modificaciones. También denominado Clasificador de Niza. Si desea consultar el clasificador haga clic aquí' },
  { term: 'Clasificador de Modelos de Utilidad', definition: 'Es Clasificador Internacional de Patentes establecido por el Arreglo de Estrasburgo del 24 de Marzo de 1971 y sus posteriores modificaciones.' },
  { term: 'Clasificador de Niza', definition: 'Clasificación de Productos y Servicios para el registro de Marcas, que permite identificar la o las clases a la cual el solicitante requiere el registro. En otras palabras, corresponde a un listado de productos y servicios organizados y ordenados en distintas clases. También denominado Clasificador de Marcas Comerciales Si desea consultar el clasificador haga **clic aquí**' },
  { term: 'Clasificador de Patentes de Invención', definition: 'Es Clasificador Internacional de Patentes establecido por el Arreglo de Estrasburgo del 24 de marzo de 1971 y sus posteriores modificaciones.' },
  { term: 'Clusters', definition: 'Concentración sectorial de empresas que se desempeñan en las mismas actividades o en actividades muy vinculadas, tanto hacia atrás, con fábricas de tecnologías, con proveedores de insumos y equipos, como hacia delante y en forma horizontal, con industrias procesadoras y usuarias, así como con servicios y otras actividades estrechamente relacionadas, con importantes y acumulativas economías externas, de aglomeración y especialización, por presencia de productores, de proveedores y mano de obra especializada, y de servicios anexos específicos al sector, y con la posibilidad de llevar a cabo una acción conjunta en búsqueda de la eficiencia colectiva.' },
  { term: 'Coberturas', definition: 'Se refiere a la descripción detallada de los productos y servicios que se desean distinguir y proteger a través de la marca comercial, cuyo registro se solicita. Se recomienda utilizar las descripciones de productos y servicios sugeridas por INAPI, que se despliegan como descripciones “Pre-Aprobadas”, pues agiliza la realización del examen formal. Si solo se utilizan descripciones Pre-Aprobadas” INAPI se compromete a notificar el resultado del examen formal en 10 días (además debe haber pagado en línea y de designar representante, debe haber dejado previamente en custodia el poder).' },
  { term: 'Códigos INID', definition: 'Códigos internacionales creados para facilitar la identificación de los datos bibliográficos de un documento de Patente (International Agreed Numbers for the Identification of Data). Significa "Identificación Numérica Internacionalmente acordada en materia de Datos (Bibliográficos). Estos códigos relacionan unívocamente un código de dos cifras con un dato bibliográfico independiente del idioma en el cual se encuentre el documento.' },
  { term: 'Comercialización', definition: 'La Comercialización es un conjunto de actividades relacionadas entre sí para cumplir los objetivos de determinada empresa. El objetivo principal es hacer llegar los bienes y/o servicios desde el productor hasta el consumidor. La comercialización se realiza por medio de diversos mecanismos de contratos como son: Licencias, Franquicia, Know-how, compra venta. En todos estos se transfiere alguno de los atributos del derecho de los activos.' },
  { term: 'Competitividad', definition: 'Capacidad de una empresa (o país) para sostener y expandir su participación en el mercado (o exportaciones). Lo que es importante para la competitividad (y la productividad) no es el tamaño de la inversión en investigación y desarrollo, sino la capacidad de enmarcar los desarrollos tecnológicos en innovaciones productivas dentro de una estrategia de la empresa (o país).' },
  { term: 'Convenio de París', definition: 'Convenio para la tramitación (al momento de la presentación) de una patente que tendrá 12 meses a partir de la fecha de presentación para depositar la solicitud de patente en cualquier otro país miembro de la Unión. (Relacionado con art. 34 ley 19.039)' },
  { term: 'Custodia de Poder', definition: 'La custodia de poder es un proceso que permite mantener en INAPI, una copia del documento que da cuenta de la facultad que se posee para representar durante la tramitación de un derecho de propiedad industrial a un solicitante de ese derecho. Esto es necesario cuando el solicitante de un registro de propiedad industrial es una empresa o varias personas quienes solicitan la marca. Dicho sistema facilita a las empresas y abogados que presentan más de una solicitud, ya que basta con citar el número de custodia en el registro de poderes. El trámite de custodia de poderes o personerías se realiza en línea Link “Custodias de poderes y personerías”' },
  { term: 'Denominaciones de Origen (DO)', definition: 'Identifica a un producto como originario de una región geográfica, atribuyéndole determinadas cualidades o reputación atribuibles fundamentalmente a su origen geográfico, teniendo en consideración además otros factores (por ejemplo humanos) que incidan en la caracterización del producto.' },
  { term: 'Derecho de autor', definition: 'El derecho de autor protege la expresión de las creaciones literarias, artísticas y científicas, durante cierto periodo de tiempo, por el sólo hecho de la creación de la obra. La protección por derecho de autor recae sobre un número indeterminado de obras, entre las que encontramos libros, obras musicales, pinturas, esculturas, películas, programas de computador o softwares, sin perjuicio de la existencia de otras obras protegidas por el derecho de autor.' },
  { term: 'Derecho moral', definition: 'Corresponden a ciertas medidas que puede tomar el autor para preservar su vínculo personal que lo une a su obra. Estos derechos son independientes de los derechos patrimoniales de que goce el autor y serán conservados por éste incluso en los casos en que se hayan cedido los derechos patrimoniales. De ahí que los derechos morales se concedan exclusivamente a autores individuales.' },
  { term: 'Derecho patrimonial', definition: 'Los derechos patrimoniales son uno de los componentes del derecho de autor y permiten al autor obtener una retribución económica por el uso de su obra por parte de terceros. En virtud de ellos, los creadores de una obra obtienen el derecho a impedir que terceros puedan utilizarla sin o contra su voluntad o autorización.' },
  { term: 'Derechos conexos', definition: 'Son derechos conexos al derecho de autor los que la Ley otorga a los artistas, intérpretes y ejecutantes para permitir o prohibir la difusión de sus producciones y percibir una remuneración por el uso público de las mismas, sin perjuicio de las que corresponden al autor de la obra.' },
  { term: 'Descriptiva (Marca)', definition: 'Dentro de los signos que carecen de distintividad se encuentran aquellos que sirven para describir los correspondientes productos y servicios. Nuestra legislación prohíbe expresamente el registro como marca de las expresiones descriptivas (art. 20/e LPI), en aras del interés público, a fin de que las expresiones descriptivas estén a disposición de todos los participantes del mercado.' },
  { term: 'Desistimiento', definition: 'Acto unilateral en cuya virtud el interesado manifiesta su voluntad de no continuar con el procedimiento administrativo iniciado de su solicitud de marca o patente. El desistimiento es procedente en cualquier estado del procedimiento (art. 18 RLPI).' },
  { term: 'Dibujo', definition: 'Es la representación gráfica de una invención e incluyen esquemas, diagramas de flujo y gráficos. Deberán realizarse en trazado técnico, en color negro debiendo omitir todo tipo de rótulo y marcos.' },
  { term: 'Dibujo Industrial', definition: 'Comprende toda disposición, conjunto o combinación de figuras líneas o colores que se desarrollan en un plano (dos dimensiones), para incorporarla a un producto industrial con fines de ornamentación, de manera que el producto presente una apariencia nueva y distinguible.' },
  { term: 'Diseño Industrial', definition: 'Es toda forma tridimensional que se distingue de sus similares, ya sea por su forma, configuración geométrica, ornamentación o una combinación de éstas, siempre que estas características le den una apariencia especial perceptible por medio de la vista. Para obtener una patente de Diseño Industrial, éste debe ser nuevo, original y tener fisonomía propia.' },
  { term: 'Diseños', definition: 'Los diseños y los dibujos industriales son títulos de propiedad industrial que protegen creaciones estéticas que agregan valor a productos determinados.' },
  { term: 'Distintividad', definition: 'Implica que el signo tenga la facultad de poder de diferenciar los bienes o servicios de una empresa de los de otras. Es por esto, que la distintividad implica que la marca puede cumplir su papel propio de identificar un producto o servicio con un origen empresarial determinado.' },
  { term: 'Distintividad extrínseca o concreta', definition: 'Es aquella que se relaciona con la existencia de otros signos similares o idénticos con anterioridad. La falta de distintividad extrínseca se encuentra recogida en las causales relativas de rechazo.' },
  { term: 'Distintividad intrínseca o abstracta', definition: 'Es aquella que se refiere a la capacidad del signo para distinguir bienes o servicios de un determinado origen empresarial. La falta de distintividad intrínseca se encuentra expresada en las causales absolutas de rechazo.' },
  { term: 'Divulgación inocua', definition: 'Es aquel en el cual el solicitante indica expresamente si existió divulgación de la invención de forma previa a la presentación de la solicitud ante el INAPI, en atención a lo señalado en el artículo 42 de la Ley 19.039.' },
  { term: 'Ejecutante', definition: 'Los ejecutantes son titulares de los derechos conexos al derecho de autor y entran en la categoría de intermediarios en la producción, grabación o difusión de las obras.' },
  { term: 'Emprendimiento', definition: 'Se trata del efecto de emprender, un verbo que hace referencia a llevar adelante una obra o un negocio. El emprendimiento suele ser un proyecto que se desarrolla con esfuerzo y haciendo frente a diversas dificultades, con la resolución de llegar a un determinado punto.' },
  { term: 'Equivalente Técnico', definition: 'Elemento o medio que realiza la misma función que aquél que está reivindicado en una invención, de la misma manera y produciendo el mismo efecto o resultado señalado en la reivindicación.' },
  { term: 'Esquema de trazados o topografías de circuitos integrados', definition: 'Los esquemas de trazados o topografías de circuitos integrados son una disposición tridimensional de elementos que componen un circuito integrado destinado a ser fabricado. Esa disposición y orden de elementos obedece a la función electrónica que dicho circuito integrado va a realizar.' },
  { term: 'Certificados de Depósito de Dibujos y Diseños Industriales', definition: 'Se trata de un Certificado obtenido a través de un procedimiento abreviado que acredita que la solicitud de Dibujo o Diseño Industrial cumple con los requisitos formales. Por lo tanto, se otorga sin realizar una búsqueda del estado de la técnica ni un examen de fondo destinado a verificar el cumplimiento de los requisitos del artículo 62 de la LPI (Art. 67 bis A y sgtes. LPI). De esta manera, confiere a su titular una fecha cierta para efectos de verificar, en un eventual examen sustantivo, el cumplimiento de los requisitos de fondo establecidos en el artículo 62 de la LPI para obtener un registro de Dibujo o Diseño Industrial, que habilita para ejercer las acciones de observancia. Tiene una duración máxima de 15 años contados desde la presentación de la solicitud y un costo de 1 UTM, que se paga junto con la presentación de la solicitud.' },
  { term: 'Estado de la Técnica', definition: 'Todo aquel conocimiento que ha sido colocado al alcance del público en cualquier parte del mundo, aunque sea totalmente desconocido en Chile, mediante una publicación en forma tangible, la venta o comercialización, el uso o cualquier otro medio, antes de la fecha de presentación de una solicitud o de la reivindicación de la prioridad de un privilegio industrial en Chile.' },
  { term: 'Examen de Fondo', definition: 'Vencido el plazo para deducir oposiciones, el o la Directora Nacional de INAPI realiza un análisis de fondo de la solicitud para determinar si concurren causales para el rechazo de oficio de la solicitud (arts. 22 LPI y 24 RLPI). Las causales de “rechazo de oficio” a que se refiere la LPI son las prohibiciones de registro contempladas fundamentalmente en los art. 19 y 20 LPI.' },
  { term: 'Examen de Forma', definition: 'Presentada una solicitud de marca o patente, el Conservador debe verificar que ésta cumpla con las formalidades exigidas para la validez de la presentación. Dichas formalidades dicen relación con los requisitos que debe contener la solicitud (art. 9 RLPI), tales como la individualización completa del solicitante y del representante; señalar de la marca (y su descripción, cuando se trata de marcas figurativas y mixtas); entre otros aspectos. En caso de poseer observaciones la solicitud, éstas pueden ser subsanadas por el mismo solicitante o representante dentro del plazo que sea determinado, y para ello no requiere patrocinio de abogado.' },
  { term: 'Examen Preliminar', definition: 'Es un examen de primera instancia donde se evalúan requisitos formales de una solicitud de patente o marca comercial, verificando si ella posee los antecedentes mínimos para iniciar su tramitación. En caso de poseer observaciones la solicitud, éstas pueden ser subsanadas por el mismo solicitante o representante dentro del plazo que sea determinado, y para ello no requiere patrocinio de abogado.' },
  { term: 'Examinador', definition: 'Profesional interno al INAPI encargado de orientar y dirigir el trabajo desarrollado por los peritos, con el objetivo de analizar los conceptos evaluados por ellos en el examen pericial y confirmar si se ha mantenido uniformidad de criterio con el subdepartamento de Patentes.' },
  { term: 'Examen Preliminar', definition: 'Es un examen de primera instancia donde se evalúan requisitos formales de una solicitud de patente o marca comercial, verificando si ella posee los antecedentes mínimos para iniciar su tramitación. En caso de poseer observaciones la solicitud, éstas pueden ser subsanadas por el mismo solicitante o representante dentro del plazo que sea determinado, y para ello no requiere patrocinio de abogado.' },
  { term: 'Exploración', definition: 'Conjunto de trabajos administrativos, de gabinete y de campo, tanto superficial como subterráneo, necesarios para localizar, estudiar y evaluar un yacimiento.' },
  { term: 'Frase de propaganda', definition: 'Las frases de propaganda o publicitarias no se encuentran definidas ni en la ley ni en su Reglamento. Sin embargo, para efectos didácticos, se puede decir que corresponden a expresiones que acompañan a una marca comercial y que se encuentran destinadas, en principio, a promocionar un bien a través de exaltar cualidades o atribuir sentimientos positivos. Éstas frases deberán ser presentadas únicamente como denominaciones y no deben estar incluidas dentro de una etiqueta.' },
  { term: 'Genérica (Marca)', definition: 'La marca genérica es por definición irregistrable, porque sirve para nombrar un producto o servicio como tal, en lugar de señalar un determinado origen empresarial. A su vez, el registro de una marca genérica significaría retirar del dominio público denominaciones, expresiones o signos que deben permanecer al alcance de todos los agentes de un determinado rubro, situación que mira el interés general del mercado.' },
  { term: 'Gestión tecnológica', definition: 'Aplicación de las técnicas de gestión en apoyo a procesos de innovación tecnológica. Integra principios y métodos de gestión (administración), evaluación, economía, ingeniería, informática y matemáticas aplicadas.' },
  { term: 'Hoja Ficha', definition: 'Formulario necesario para iniciar la tramitación de una solicitud de patente, modelo de utilidad o diseño industrial, que resumen los datos básicos de la solicitud: título, inventor, tipo de solicitud, representante, etc.' },
  { term: 'Hoja Técnica', definition: 'Formulario que en términos simples, corresponde a la carátula o portada de la solicitud. En ella se encuentran antecedentes administrativos y técnicos de la solicitud, como son un resumen de la invención y una figura representativa.' },
  { term: 'I+D', definition: 'Se denomina Investigación y Desarrollo al conjunto de acciones realizadas sistemáticamente para desplazar la frontera del conocimiento y derivar nuevas aplicaciones.' },
  { term: 'I+D+i', definition: 'Investigación, Desarrollo e Innovación.' },
  { term: 'IG/DO', definition: 'Las Indicaciones Geográficas y las Denominaciones de Origen (IG/DO) protegen ciertos productos caracterizados por provenir de cierta y determinada región geográfica o por estar producido de la forma y con la técnica de cierta y determinada región geográfica. En este sentido, como títulos de propiedad industrial se tratan de verdaderos signos distintivos de determinados productos.' },
  { term: 'Incubadoras de negocio', definition: 'Son centros de apoyo que te ayudan a montar tu empresa. Las incubadoras se encargan de evaluar la viabilidad técnica, financiera y de mercado de tu proyecto empresarial, asi también te proporcionan servicios integrales de asesoría legal y administrativa, así como planes de mercadotecnia y ventas, e incluso espacio físico, equipo, logística y hasta acceso a financiamiento y capital semilla.' },
  { term: 'Indicaciones Geográficas (IG)', definition: 'Una indicación geográfica es un signo utilizado para productos que tienen un origen geográfico concreto y poseen cualidades o una reputación derivadas específicamente de su lugar de origen. Por lo general, una indicación geográfica consiste en el nombre del lugar de origen de los productos.' },
  { term: 'Indicativas (marcas)', definition: 'La Ley de Propiedad Industrial prohíbe también registrar como marcas comerciales aquellas expresiones o signos empleados para indicar, respecto de los productos, servicios o establecimientos, el/la: Naturaleza ; Origen, nacionalidad, procedencia; Destinación; Peso, valor; Cualidad.' },
  { term: 'Informe o Examen Pericial', definition: 'Es un documento elaborado por el perito, que refleja el resultado de contrastar la solicitud de patente con los documentos del estado de la Técnica, para determinar si ésta cumple con los requisitos necesarios para ser concedida como patente.' },
  { term: 'Innovación', definition: 'Es la creación o modificación de un producto o proceso y su introducción en un mercado que a su vez soluciona un problema de la técnica.' },
  { term: 'Intérprete', definition: 'Los intérpretes son titulares de los derechos conexos al derecho de autor y entran en la categoría de intermediarios en la producción, grabación o difusión de las obras.' },
  { term: 'Invención', definition: 'Es una solución nueva a un problema técnico, que genera actividad industrial, pudiendo dicha solución estar dada por un producto o un procedimiento. Para obtener una patente de invención, la invención debe ser nueva, inventiva y susceptible de aplicación industrial.' },
  { term: 'Invenciones con patente vigente', definition: 'Aquellas cuya patente está dentro del plazo de protección en el territorio nacional. Para su uso el titular (propietario) debe expresamente autorizarlo. Para esto, el interesado debe contactarse con los creadores y acordar los términos del licenciamiento. La utilización maliciosa de una invención es sancionada por la Ley de acuerdo al artículo 52 titulo X de la Ley 19.039.' },
  { term: 'Ley Nº 19039', definition: 'Ley que establece las normas aplicables a los derechos de Propiedad Industrial y su protección. Publicada en el Diario Oficial el 25 de Enero de 1991.' },
  { term: 'Invenciones o innovaciones de dominio público', definition: 'Son aquellas en que la protección provista por la patente ha cesado debido a causas establecidas por ley. Es decir, ha terminado el tiempo de protección, no ha sido solicitada en el territorio nacional aun estando vigente en otros países o fue abandonada. De igual forma, se considera dominio público aquello en que su creador renuncia a la propiedad intelectual y por lo tanto puede ser utilizado por cualquier persona. Se recomienda siempre obtener una autorización expresa.' },
  { term: 'Inventor', definition: 'Es la persona o personas naturales que han desarrollado una invención.' },
  { term: 'Investigación aplicada', definition: 'Actividad planificada, que en la mayoría de los casos toma como base el conocimiento generado en una investigación básica, que busca encontrar soluciones a través de productos o servicios para mejorar la calidad de vida de las personas y la sociedad.' },
  { term: 'Investigación básica', definition: 'Actividad planificada, experimental o teórica, cuyo objetivo es la obtención de nuevos conocimientos que supongan un avance para la ciencia y la tecnología.' },
  { term: 'Investigación tecnológica', definition: 'Actividad orientada a la generación de nuevo conocimiento tecnológico que pueda ser aplicado directamente a la producción y distribución de bienes y servicios; puede conducir a una invención, una innovación o una mejora (una aplicación menor). La investigación tecnológica no es la única fuente de cambios en la tecnología.' },
  { term: 'Investigación y desarrollo experimental', definition: 'Trabajo creativo realizado de manera sistemática con el fin de aumentar el conocimiento y utilizarlo para desarrollar nuevas aplicaciones.' },
  { term: 'Investigadores', definition: 'Son profesionales que trabajan en la Investigación y creación de nuevos conocimientos, productos, procesos, métodos, y en la gestión de los respectivos proyectos.' },
  { term: 'IPCAT', definition: 'Herramienta de categorización de patentes basado en la CIP, a la cual se accede a través del sitio de la OEPM http://cip.oepm.es/. Está diseñada principalmente para ayudar a clasificar las patentes a nivel de subclase.' },
  { term: 'Join venture', definition: 'Formación de una empresa conjunta con el fin de desarrollar y explotar una nueva tecnología (normalmente personas jurídicas o comerciantes).' },
  { term: 'Know-How', definition: 'Es una forma de transferencia de tecnología utilizada en los últimos tiempos en el comercio internacional para denominar los conocimientos preexistentes no siempre académicos, que incluyen: técnicas, información secreta, teorías e incluso datos privados (como clientes o proveedores). Con el Know How se obtiene exclusividad para utilizar y mantener la propiedad industrial sobre un proceso u objeto. De esta forma, se usa como una gran ventaja competitiva al hacer el producto más valioso. Es importante considerar que el proceso en cuestión ha de ser algo novedoso y distinto.' },
  { term: 'Licencia', definition: 'Contrato por el cual el titular de un derecho autoriza a un tercero para ejercer el derecho de explotación (de un derecho de PI), durante determinado tiempo, a cambio o no de una regalía (royalty).' },
  { term: 'Licencia de Marca Comercial o Patente', definition: 'Es un permiso o facultad que otorga el dueño de la marca o patente ya registrada a un tercero. Este último, puede utilizar el registro en las condiciones que la propia escritura de licencia entre las partes señale.' },
  { term: 'Licencia exclusiva', definition: 'Un solo licenciatario tiene derecho a utilizar la tecnología patentada, que no podrá utilizar nadie, incluido el titular de la patente.' },
  { term: 'Licencia no exclusiva', definition: 'Varios licenciatarios y el titular de la patente tienen derecho a utilizar la tecnología patentada.' },
  { term: 'Licencia no voluntaria', definition: 'Es la autorización que confiere la autoridad competente a un tercero para utilizar una invención sin o en contra de la voluntad de su titular, por haberse configurado una situación de abuso monopólico.' },
  { term: 'Licencia única', definition: 'Un solo licenciatario y el titular de la patente tiene derecho a utilizar la tecnología patentada.' },
  { term: 'Licenciamiento', definition: 'Cesión de derechos de explotación de Propiedad Intelectual e Industrial (tecnología).' },
  { term: 'Lixiviación', definition: 'Proceso que permite obtener cobre a partir de minerales oxidados, aplicando disolución de ácido sulfúrico y agua.' },
  { term: 'Marca colectiva', definition: 'Todo signo o combinación de signos capaz de distinguir en el mercado los productos o servicios de los miembros de una asociación respecto de los productos o servicios de terceros. Para estos efectos se entenderá por asociación a las agrupaciones de productores, fabricantes, comerciantes o prestadores de servicios que gocen de personalidad jurídica. La marca colectiva no podrá cederse a terceras personas.' },
  { term: 'Marca Comercial', definition: 'Es todo signo capaz de distinguir en el mercado productos o servicios. Tales signos podrán consistir en palabras, incluidos los nombres de personas, letras, números, elementos figurativos tales como imágenes, gráficos, símbolos, combinaciones de colores, sonidos, olores o formas tridimensionales, así como también, cualquier combinación de estos signos. Cuando los signos no sean intrínsecamente distintivos, podrá concederse el registro si han adquirido distintividad por medio del uso en el mercado nacional.' },
  { term: 'Marca de certificación', definition: 'Todo signo o combinación de signos capaz de distinguir en el mercado los productos o servicios de terceros, garantizando que éstos cumplen con requisitos y características comunes. No podrán ser titulares de marcas de certificación quienes fabriquen o comercialicen productos o servicios idénticos o similares a aquéllos a los que fuere a aplicarse la citada marca. El titular de una marca de certificación deberá autorizar su uso a toda persona cuyo producto o servicio cumpla las condiciones establecidas en el reglamento de uso de la marca.' },
  { term: 'Marca Denominativa', definition: 'Son una palabra o palabras, con o sin significado idiomático, combinación de letras, y/o número. Según el art. 19 LPI, se pueden incluir en las marcas denominativas los siguientes elementos: Nombres de personas, Letras, Números, Palabras. No son reivindicables en su parte denominativa - sí en las marcas mixtas- elementos, tales como: Color de letra, Estilización de caracteres, Mayúscula o Minúscula, utilizados, Puntuación, Signos de exclamación' },
  { term: 'Marcas figurativas', definition: 'Etiquetas con figuras, imágenes, símbolos, dibujos.' },
  { term: 'Marca sonora', definition: 'Las marcas sonoras son aquellos sonidos que tiene la capacidad de distinguir un determinado origen empresarial y que pueden registrarse como marca comerciales.' },
  { term: 'Marca Mixta', definition: 'Marcas Mixtas son las correspondientes a etiquetas con palabra o palabras, con o sin significado idiomático, combinación de letras, y/o número, en combinación con figuras, imágenes, símbolos o dibujos. Se establece en el Art. 19 que los signos también pueden consistir en una combinación de los signos compuestos por marcas denominativas y figurativas a la vez.' },
  { term: 'Marcas', definition: 'Es todo signo capaz de distinguir en el mercado productos o servicios. Tales signos podrán consistir en palabras, incluidos los nombres de personas, letras, números, elementos figurativos tales como imágenes, gráficos, símbolos, combinaciones de colores, sonidos, olores o formas tridimensionales, así como también, cualquier combinación de estos signos. Cuando los signos no sean intrínsecamente distintivos, podrá concederse el registro si han adquirido distintividad por medio del uso en el mercado nacional. Solicita tu registro de marca' },
  { term: 'Marcas de productos', definition: 'Son signos susceptibles de representación gráfica capaz de distinguir en el mercado productos, con el objeto de que el público consumidor los diferencie de otros de la misma especie o idénticos existentes en el mercado.' },
  { term: 'Marcas de servicios', definition: 'Una marca de servicio es un signo susceptible de representación gráfica capaz de distinguir en el mercado servicios, con el objeto que el público consumidor los diferencie de otro de la misma especie o idénticos que existan en el mercado. Es decir son signos que indican que un servicio es suministrado por una empresa determinada.' },
  { term: 'Marcas denominativas', definition: 'Una palabra, o palabras, con o sin significado idiomático, combinación de letras, o número.' },
  { term: 'Marcas famosas o renombradas', definition: 'Son aquellas internacionalmente o mundialmente conocidas. Una de las características de las marcas famosas y renombradas es que corresponde una excepción al principio de especialidad de las marcas, es decir, se puede entender que existe error o confusión en marcas de productos o servicios entre los cuales no existe relación de cobertura, no considerando el principio de especialidad.' },
  { term: 'Marca Figurativa', definition: 'Marcas figurativas o signo distintivo son las etiquetas con figuras, imágenes, símbolo o dibujos. Según el art. 19 LPI, las etiquetas pueden consistir en los siguientes elementos: Imágenes, Gráficos, Símbolos, Combinaciones de colores. La etiqueta presentada por el solicitante es esencial para la tramitación de la marca y por esto, debe ser acompañada de la forma como se quiere registrar.' },
  { term: 'Marcas mixtas', definition: 'Etiquetas con palabra, o palabras, con o sin significado idiomático, combinación de letras, o número, en combinación con figuras, imágenes, símbolos, o dibujos.' },
  { term: 'Marcas notorias', definition: 'Son aquellas que son conocidas por un amplio porcentaje de los consumidores. El conocimiento debe ser dentro de las fronteras nacionales con independencia de si se encuentra registrada o no.' },
  { term: 'Memoria Descriptiva', definition: 'Documento mediante el cual el solicitante de un privilegio industrial da a conocer en forma clara y detallada su invención, o modelo de utilidad o diseño industrial y, además, el estado del arte relacionado con dicho privilegio. Debe ser escrita en hojas blancas en tamaño Oficio o A4\\. Debe contener las partes descritas en el Artículo 43º del Reglamento de la Ley Nº 19.039.' },
  { term: 'Modelos de utilidad', definition: 'Es una creación que pretende entregar una configuración o forma tridimensional nueva a objetos conocidos, o partes de los mismos, que se utilicen para realizar un trabajo práctico, siempre que esta nueva configuración produzca una mejor utilización del objeto en la función a la que está destinado. Para obtener una patente de Modelo de Utilidad, éste debe ser nuevo y susceptible de aplicación industrial.' },
  { term: 'MPS (Método Problema-Solución)', definition: 'Es una herramienta de análisis de nivel inventivo que se propone como metodología estándar de evaluación de este requisito de patentabilidad, adecuando algunos de sus elementos o etapas a la actual práctica del Instituto Nacional de Propiedad Industrial (INAPI).' },
  { term: 'Nanotecnología', definition: 'Es el estudio, diseño, creación, síntesis, manipulación y aplicación de materiales funcionales y sistemas de control de la materia a escalas del nanómetro (la mil millonésima parte de un metro) o tecnologías comparables a la longitud de una pequeña molécula. A esta escala, la materia presenta propiedades diferentes que pueden ser aplicadas al desarrollo de nuevas tecnologías que ofrecen soluciones a una gran variedad de problemas actuales de la industria, investigación médica y el medio ambiente.' },
  { term: 'Nivel Inventivo', definition: 'Requisito de patentabilidad para las invenciones que implica que los resultados del proceso creativo no son deducibles, por una persona versada en la materia, de la técnica conocida o divulgada, de manera evidente u obvia.' },
  { term: 'No Presentación', definition: 'Instancia administrativa a la cual llega una solicitud en el caso de que el solicitante no de respuesta a observaciones efectuadas en el examen preliminar, dentro del plazo que establece la Ley Nº 19039\\. La solicitud que cae dentro de esta situación perderá su fecha de primera presentación (prioridad).' },
  { term: 'Nombres de Dominio', definition: 'Los nombres de dominio son direcciones de Internet fáciles de recordar y suelen utilizarse para identificar sitios Web. Por ejemplo, el nombre de dominio inapi.cl se utiliza para ubicar el sitio Web de INAPI en Chile www.inapi.cl. Los nombres de dominio constituyen también la base de otros métodos o aplicaciones en Internet, como la transferencia de ficheros y las direcciones de correo electrónico. Los nombres de dominio sirven como un primer mecanismo de protección de una idea, producto, servicio y puede ser tramitado previo a una marca particular.' },
  { term: 'Notificaciones', definition: 'Corresponde al acto de poner una resolución en conocimiento del interesado o de terceros.' },
  { term: 'Notoria (Marca)', definition: 'Las marcas notorias se definen como aquellas que por su volumen de ventas, duración o intensidad de uso en el mercado, por su valoración o prestigio alcanzado, o por cualquier otra causa similar, es indudablemente conocida por el sector pertinente del público al que se destinan los productos, servicios o establecimientos. Estos elementos deben ser probados por quien alega que se está ante una marca notoria.' },
  { term: 'Novedad', definition: 'Requisito de patentabilidad para las invenciones, modelos de utilidad y diseños industriales que implica que el objeto de la solicitud no existe, no se ha divulgado o no se ha hecho accesible al público mediante cualquier medio de difusión o información en cualquier lugar del mundo, con anterioridad a la fecha de presentación de la solicitud al INAPI o a la fecha de prioridad.' },
  { term: 'Número de solicitud', definition: 'Número asignado por INAPI al momento de ingresar la marca al proceso de tramitación.' },
  { term: 'OMPI', definition: 'La Organización Mundial de la Propiedad Intelectual (OMPI) es un organismo especializado del sistema de organizaciones de las Naciones Unidas. Su objetivo es desarrollar un sistema de propiedad intelectual (P.I.) internacional, que sea equilibrado y accesible, y recompense la creatividad, estimule la innovación y contribuya al desarrollo económico, salvaguardando a la vez el interés público.' },
  { term: 'Oposición', definition: 'Instancia administrativa en la cual un tercero presenta objeciones a una solicitud de patente o marca comercial por considerar afectados sus intereses. El escrito de oposición y el de contestación a ella, deberán ser patrocinados por un abogado habilitado para el ejercicio de la profesión.' },
  { term: 'Originalidad', definition: 'Requisito de patentabilidad para diseños industriales que se cumple cuando se observa que el objeto de la solicitud obedece a una creación directa de su autor, sin denotar la existencia de un estudio de imitación, es decir, es fruto de una creación espontánea y no copiada. No será original, un diseño industrial que superpone o integra dos o más partes de productos u objetos bien conocidos.' },
  { term: 'Palabra clave', definition: 'Son palabras o términos específicos que describen el ámbito fundamental de una invención.' },
  { term: 'Palabra o denominación', definition: 'Opción que se utiliza para solicitar Marcas denominativas, esto es una palabra o palabras, con o sin significado idiomático, combinación de letras o números.' },
  { term: 'Patente', definition: 'Es un derecho de exclusividad, concedido por el Estado, para proteger y explotar una invención por el tiempo que determine la Ley.' },
  { term: 'Patente Provisional', definition: 'Es aquella solicitud que puede presentarse sin acompañar todos los documentos exigidos en los Arts. 43, 43 bis y 58 Ley N° 19.039, confiriendo a su titular un derecho de prioridad por el plazo de un año, contado desde su presentación, para presentar una solicitud definitiva. La solicitud de patente provisional no requiere la presentación de reivindicaciones. Al respecto, bastará que se presente un documento en inglés o español que describa la invención o el modelo de utilidad de manera suficientemente clara y completa y de ser necesario, acompañe al menos un dibujo. Posteriormente, el plazo para presentar la solicitud de patente definitiva es de 12 meses contado desde la presentación de la solicitud provisional. Si no se presentase la solicitud definitiva dentro de dicho plazo, se tiene por no presentada la solicitud de patente provisional. La solicitud de patente provisional puede ser utilizada como prioridad de una solicitud PCT, luego cuando corresponda la presentación en fase nacional, se podrá presentar una solicitud en INAPI, que tendrá el efecto de una solicitud definitiva. La solicitud de patente provisional no es pública, sino hasta que se publica el extracto de la solicitud definitiva. El plazo de vigencia de la solicitud de patente definitiva se contará desde la fecha de presentación de la solicitud provisional.' },
  { term: 'Patente de dominio público', definition: 'Registros de patentes en los cuales su plazo de vigencia ha caducado.' },
  { term: 'Patentes', definition: 'Una patente es un derecho de exclusividad concedido por el Estado, para proteger y explotar una invención por el tiempo que determine la Ley.' },
  { term: 'Patentes de invención', definition: 'Se entiende por patente de invención toda solución a un problema de la técnica que origine un quehacer industrial. Una invención podrá ser un producto o un procedimiento o estar relacionada con ellos.' },
  { term: 'Patentes vigentes', definition: 'Registros de patentes concedidos por INAPI y que cumplen con los requisitos solicitados para la obtención de un derecho de propiedad industrial.' },
  { term: 'Propiedad Intelectual', definition: 'El término propiedad intelectual se refiere a la protección del producto del intelecto humano, sea en los campos científicos literarios, artísticos o industriales. Esa protección concede a los creadores, autores e inventores un derecho temporal para excluir a los terceros de la apropiación de conocimiento por ellos generados.' },
  { term: 'Patrocinio', definition: 'Acto solemne puesto que se entiende constituido “por el hecho de poner el abogado su firma, indicando además, su nombre, apellidos y domicilio” (art. 1 inc. 2 ley 18.120).' },
  { term: 'PCT', definition: 'El Tratado de Cooperación en materia de Patentes (PCT), es un tratado internacional administrado por la Organización Mundial de Propiedad Intelectual (OMPI), cuyo objetivo principal es simplificar y hacer más económico para los usuarios del sistema de patentes y las oficinas encargadas de administrarlo, el procedimiento para la presentación de una solicitud internacional de patente, con miras a proteger las invenciones en varios países.' },
  { term: 'Personas jurídicas', definition: 'Sociedades comerciales, fundaciones y corporaciones, organismos gubernamentales, municipalidades, universidades, sucesiones, gremios, comunidades y asociaciones indígenas.' },
  { term: 'Personas naturales', definition: 'Solicitante individual, dos o más solicitantes en conjunto.' },
  { term: 'Pliego de Reivindicaciones', definition: 'Consiste en un grupo de peticiones ordenadas y enlazadas definiendo la materia que será objeto de protección. Estarán precedidas de un número arábico y serán tantas como sean necesarias para definir y delimitar correctamente la invención.' },
  { term: 'Poder', definition: 'Es el documento a través del cual el solicitante indica quien lo representará ante el INAPI u otra institución, si fuese el caso, y cuáles son las facultades que éste tiene.' },
  { term: 'Políticas de gobierno', definition: 'Se refiere al grado en que las políticas del gobierno tienen como objetivo el apoyar a las empresas nuevas y en crecimiento y ser neutras sobre el funcionamiento de las ya establecidas.' },
  { term: 'Principio de especialidad', definition: 'Uno de los principios base del derecho marcario es el principio de especialidad que consiste en la exclusividad del uso de la marca comercial sólo para determinados productos o servicios que la marca cubre. El principio de especialidad marcaria es el límite externo de la protección marcaria. Lo anterior se manifiesta en el artículo 19 bis D de la Ley 19.039 el cual señala que: " La marca confiere a su titular el derecho exclusivo y excluyente de utilizarla en el tráfico económico en la forma que se le ha conferido y para distinguir los productos o servicios comprendidos en el registro.' },
  { term: 'Prioridad o Derecho de Prioridad', definition: 'El Derecho de prioridad es el mejor derecho del peticionario sobre otras solicitudes presentadas con posterioridad a la suya y nace desde el momento que presenta su solicitud. La Ley 19039 en el art. 20 bis hace mención de las marcas que han sido presentadas previamente en el extranjero y establece un plazo de 6 meses contados desde la fecha de su presentación en el país de origen, para presentar la solicitud en Chile. La prioridad podrá acreditarse de acuerdo a los medios y modalidades establecidas en el reglamento.' },
  { term: 'Productor fonográfico', definition: 'Los productores fonográficos son titulares de los derechos conexos al derecho de autor y entran en la categoría de intermediarios en la producción, grabación o difusión de las obras.' },
  { term: 'Propiedad Industrial', definition: 'Comprende, principalmente, creaciones asociadas a una finalidad comercial. De acuerdo a la Ley 19.039 son derechos de propiedad industrial las patentes de invención, modelos de utilidad, diseños y dibujos industriales, esquemas de trazado o topografías de circuitos integrados, marcas comerciales, indicaciones geográficas y denominaciones de origen.' },
  { term: 'Prospectiva tecnológica', definition: 'Determinación de la posible evolución futura de las dimensiones tecnológicas de una determinada tecnología incorporada o desincorporada, o un producto, un proceso, un equipo o un servicio.' },
  { term: 'Publicación', definition: 'Es la instancia administrativa en la cual la solicitud de patente o marca comercial se da a conocer al público a través de la divulgación de un título representativo de ella en el Diario Oficial.' },
  { term: 'Reclamación', definition: 'El recurso de reclamación es un medio de impugnación especial que la LPI concede al interesado cuya solicitud ha sido declarada abandonada por el Conservador de Marcas —al no haberse cumplido una observación de forma— para recurrir a la Directora Nacional de INAPI a fin de que esta última revoque la resolución.' },
  { term: 'Regalía', definition: 'Retribución o pago periódico que el licenciatario debe al titular de un privilegio industrial, por la licencia de uso otorgada sobre un derecho de propiedad industrial.' },
  { term: 'Registros en Internet', definition: 'Los registros en Internet funcionan separados de los registros de Propiedad Intelectual. Sin embargo, el registro previo de una marca sienta un precedente ante las oficinas de registro internet en caso de una reclamación.' },
  { term: 'Marca Tridimensional', definition: 'Es aquella que consiste en, o incluye, una forma tridimensional, incluidos los recipientes, el embalaje, el producto mismo o su apariencia, estará representada por la presentación o bien de una reproducción gráfica de dicha forma, incluidas las imágenes generadas por ordenador, o bien de una reproducción fotográfica.' },
  { term: 'Reglamento de la Ley Nº 19.039', definition: 'Decreto Supremo que establece las normas para aplicar la Ley Nº 19039, sobre derechos de Propiedad Industrial. Publicado en Diario Oficial el 30 de Septiembre de 1991.' },
  { term: 'Reivindicación Dependiente', definition: 'Es aquella que contiene las características de otra reivindicación y que precisa los detalles o alternativas adicionales para las que la protección se solicita.' },
  { term: 'Reivindicación Dependiente Múltiple', definition: 'Es aquella que se refiere a más de una reivindicación anterior.' },
  { term: 'Reivindicación Independiente', definition: 'Es aquella de la misma categoría (producto, procedimiento o aparato) que se utiliza si el objeto de la solicitud o unidad de invención no puede ser cubierto adecuadamente por una reivindicación.' },
  { term: 'Reivindicación o cláusula', definition: 'Es la enunciación y delimitación de lo que en definitiva queda protegido por una patente de invención o modelo de utilidad y cuya estructura es la siguiente: Número de la cláusula; Preámbulo; La expresión "caracterizado"; y La caracterización.' },
  { term: 'Renovación de Marca', definition: 'La marca registrada tiene una duración de diez años, contados desde la fecha de su inscripción en el registro respectivo. El titular tiene el derecho de pedir su renovación por períodos iguales durante los seis meses anteriores al vencimiento de su vigencia y hasta seis meses contados desde su expiración, cumpliendo con lo establecido respecto al pago de las tasas establecidas en la Ley. Vencido el plazo señalado anteriormente y sin que se presente la solicitud de renovación, el registro caducará.' },
  { term: 'Representante', definition: 'Figura declarada por el solicitante, a quien se le han dado las atribuciones necesarias para realizar la tramitación de la solicitud frente al INAPI.' },
  { term: 'Revisión Formal de Patente', definition: 'Es la instancia administrativa correspondiente a la última revisión de la solicitud previo a la concesión del registro de patente. En esta etapa se revisan detalles administrativos y formales y, además, se ordena la solicitud.' },
  { term: 'Secreto', definition: 'Se puede considerar como secreto empresarial todo conocimiento sobre productos o procedimientos industriales, cuyo mantenimiento en reserva proporciona a su poseedor una mejora, avance o ventaja competitiva.' },
  { term: 'Secreto industrial', definition: 'Corresponde a toda información no divulgada que una persona posea bajo su control y que pueda usarse en alguna actividad productiva, industrial o comercial, siempre que cumpla las siguientes condiciones: a) Sea secreta en el sentido de no ser, como conjunto o en la configuración y reunión precisas de sus componentes, generalmente conocida, ni fácilmente accesible para personas que se encuentran en los círculos en los que normalmente se utiliza ese tipo de información; b) Tenga un valor comercial por ser secreta; y c) Haya sido objeto de medidas razonables tomadas por su legítimo poseedor para mantenerla secreta.' },
  { term: 'Solicitante', definition: 'Es la(s) persona(s), empresa(s), institución(es) que está solicitando al Estado de Chile que le confiera el derecho, por tanto quien(es) se registren en esta categoría será(n) el (los) propietario(s) de la marca o patente.' },
  { term: 'Solicitud de Patente', definition: 'Esta solicitud le permitirá obtener un derecho exclusivo que concede el Estado para la protección de una Invención, modelo de utilidad, diseño industrial. Los efectos, obligaciones y limitaciones inherentes a la patente están determinados por la Ley 19.039 de Propiedad Industrial. El titulo del invento deberá ser breve, claro y preciso, de tal modo que cualquier persona versada en la técnica o arte pueda formarse una idea del cuál es el problema técnico que resuelve y la forma que este soluciona. En ningún caso se admitirán palabras de fantasía que tengan un significado claramente establecido en la técnica o especialidad de que se trate.' },
  { term: 'Solicitud de Productos', definition: 'Con ella se pretende distinguir un determinado artículo o producto tangible de cualquier naturaleza que sean estos.' },
  { term: 'Solicitud de Servicios', definition: 'Con ella se pretende distinguir una determinada prestación intangible que se ofrece a terceros, pudiendo ser ésta de la más variada naturaleza (Asesorías, construcciones, consultorías, etc).' },
  { term: 'Solicitud Frase de Propaganda', definition: 'Con ella se pretende destacar una determinada cualidad o característica de una marca ya registrada, trátese ésta última de productos, servicios, establecimiento comercial o industrial. Es indispensable, para acceder a este tipo de registro, el poseer o ser titular de una marca ya registrada. La frase de Propaganda debe ser inscrita en la misma clase y con idéntica cobertura que la marca inscrita. La Frase de Propaganda NO puede ser asociada a diferentes registros, involucra necesariamente uno solo.' },
  { term: 'Teoría Científica', definition: 'Conocimiento relacionado con alguna ciencia y considerado especulativo, con independencia de toda aplicación.' },
  { term: 'Territorialidad', definition: 'Los derechos de propiedad industrial son territoriales. Esto significa que el titular sólo gozará de protección y por ende de los derechos que le son conferidos en aquellos países o regiones donde se ha obtenido protección. En otras palabras, si no se le ha concedido una patente, marca, indicación geográfica o denominación de origen en un país determinado, éstos no estarán protegidos en ese país, lo que permitirá a cualquier otra persona fabricar, utilizar, importar o vender su invención en ese país.' },
  { term: 'Transferencia de I+D', definition: 'Se refiere a la medida en que la investigación y el desarrollo conducen a generar nuevas oportunidades comerciales y si estas están al alcance de las empresas nuevas, las pequeñas y las que están en crecimiento.' },
  { term: 'Transferencia Parcial', definition: 'Corresponde a la solicitud que se aplica en el caso que el titular de una marca desee vender, ceder o transferir parcialmente a un tercero. A diferencia de la Transferencia Total, se permite desglosar o parcializar la cobertura del registro. Este registro, de idéntica marca, queda a nombre de dos titulares distintos. Si el dueño del registro abarca dentro de su cobertura solamente productos de una clase, NO puede transferir parcialmente dicha clase. Sin embargo, respecto al establecimiento comercial, es posible transferir parcialmente el registro si ello implica que los establecimientos funcionarán en distintas regiones. En los casos de transferencia de registros, deberán igualmente transferirse las frases de propaganda que se asocian a esos registros, ya que ellas (frases de propaganda) no pueden tener una existencia independiente.' },
  { term: 'Transferencia tecnológica', definition: 'La transferencia de tecnología es una serie de procesos destinados a compartir ideas, conocimientos, tecnologías y capacidades con otro particular o institución (por ejemplo, una empresa, una universidad o un organismo gubernamental) y la adquisición por la otra parte de esas ideas, conocimientos, tecnologías y capacidades.' },
  { term: 'Transferencia Total', definition: 'Corresponde a la solicitud que se utiliza en el caso que el titular de, una marca registrada o patente, venda, ceda, o transmita (por sucesión por causa de muerte) un determinado registro a un tercero. En el caso de marcas, la solicitud de transferencia comprende un solo registro, NO siendo posible transferir varias inscripciones en una misma solicitud. La cobertura que el registro ampara, trátese de productos, servicios, establecimiento comercial o industrial, se transfiere íntegramente, NO siendo posible desglosarlo o parcializarlo en ninguna de sus partes.' },
  { term: 'Transgénico', definition: 'Organismo modificado genéticamente.' },
  { term: 'Tratado sobre el Derecho de Marcas (TLT)', definition: 'Tratado administrado por la OMPI y tiene como principal objetivo simplificar y armonizar los procedimientos administrativos nacionales relativos al registro de marcas. Dicho tratado fue aprobado por el Congreso Nacional de Chile en septiembre de 2010. A fin de adecuar la normativa interna a las disposiciones de dicho tratado, se dictó la ley 20.569 (que modificó la ley 19.039 de propiedad industrial), publicada en el Diario Oficial con fecha 6 de febrero de 2012 y con vigencia desde igual fecha.' },
  { term: 'Tribunal Arbitral', definition: 'El tribunal especial establecido en el artículo 17º de la Ley.' },
  { term: 'Unidad de Invención', definition: 'Concepto que hace referencia al hecho de que en una solicitud de patente pueden existir múltiples reivindicaciones independientes, sin embargo, éstas deben estar amparadas bajo una idea común e inventiva.' },
  { term: 'Variedades vegetales', definition: 'Variedad vegetal es un conjunto de plantas de un solo taxón botánico, o sea el elemento distintivo del rango más bajo conocido que, con independencia de si responde o no plenamente a las condiciones para la concesión de un derecho del obtentor, puede: 1. Definirse por la expresión de los caracteres resultantes de un cierto genotipo o de una cierta combinación de genotipos. 2. Distinguirse de cualquier otro conjunto de plantas por la expresión de uno de dichos caracteres por lo menos. 3. Considerarse como una unidad, habida cuenta de su aptitud a propagarse sin alteración.' },
  { term: 'Vigilancia tecnológica', definition: 'La Vigilancia Tecnológica es una forma sistemática de captación y análisis de información científico-tecnológica que sirve de apoyo en los procesos de toma de decisiones. A través de los estudios de Vigilancia Tecnológica, se detectan fuentes de información esenciales para hacer frente a las decisiones tecnológicas, se extrae información relevante sobre tendencias tecnológicas, novedades, invenciones, potenciales socios o competidores, aplicaciones tecnológicas emergentes, a la vez que se contemplan aspectos regulatorios y de mercado que pueden condicionar el éxito de una innovación tecnológica. Toda esta información codificada y analizada brinda a un decisor, ya sea una empresa o institución científica, la posibilidad de trazar planes y formular estrategias tecnológicas, minimizando la incertidumbre.' },
]
